def get_licenses(*, session: requests.Session, db_mirror: Union[Optional[
    str], bool]=False, cached: int=0, telemetry: bool=True) ->Dict[str, Any]:

    if not session.api_key:
        raise InvalidCredentialError(credential=session.get_credential(), reason="No API key provided")

    if db_mirror is False:
        # Use API mirror
        try:
            data = fetch_database_url(
                session=session,
                mirror=API_MIRRORS[0],
                db_name="licenses.json",
                cached=cached,
                telemetry=telemetry,
                ecosystem=Ecosystem.PYTHON,
                from_cache=True
            )
            return data
        except Exception as e:
            if isinstance(e, (InvalidCredentialError, TooManyRequestsError, DatabaseFetchError, ServerError)):
                raise e
            raise DatabaseFetchError()
    elif isinstance(db_mirror, str):
        # Use local file mirror
        try:
            data = fetch_database_file(
                path=db_mirror,
                db_name="licenses.json",
                cached=cached,
                ecosystem=Ecosystem.PYTHON
            )
            return data
        except DatabaseFileNotFoundError:
            raise DatabaseFileNotFoundError(db=db_mirror)
        except Exception:
            raise DatabaseFetchError()
    else:
        # db_mirror is True or some other truthy value, treat as API
        try:
            data = fetch_database_url(
                session=session,
                mirror=API_MIRRORS[0],
                db_name="licenses.json",
                cached=cached,
                telemetry=telemetry,
                ecosystem=Ecosystem.PYTHON,
                from_cache=True
            )
            return data
        except Exception as e:
            if isinstance(e, (InvalidCredentialError, TooManyRequestsError, DatabaseFetchError, ServerError)):
                raise e
            raise DatabaseFetchError()
